// The `tick` hook point (once per tick, in every Game (check game.native_window())).
// Generated by horizon-port from Entity Sound Features 0.8.2. It stands in for:
//   The mod's initializer, run once on the first tick
fn entity_sound_features_tick(game: &mut crate::game::Game<'_>) {
    use crate::game::port_entity_sound_features as m;
    // Turned off in Options > Mods: nothing until the next build leaves it out.
    if !game.native_on(m::ID) {
        return;
    }
    // The mod's data folder and its initializer, the first time.
    crate::game::port_entity_sound_features_game::ensure_init(game);
    let _ = (game, &m::ID);
}
